def main(query):
    import sys
    import platform
    import re

    numbers = [float(x) for x in re.findall(r"-?\d+(?:\.\d+)?", str(query or ""))]
    stats = {}
    if numbers:
        stats = {
            "count": len(numbers),
            "sum": sum(numbers),
            "mean": sum(numbers) / len(numbers),
            "min": min(numbers),
            "max": max(numbers),
        }

    return {
        "python_version": sys.version,
        "platform": platform.platform(),
        "query_recue": str(query),
        "nombres_detectes": numbers,
        "stats": stats,
    }

